INSERT INTO public.directory_entities (id,name,tipo,ambito,cats,rol,org,description,url,tags,datos,soc,rel,dir,geo_precision,zone_id,subzone_id,lat,lon,conf,flag,fuentes,estado,notas,orden,visibility,source_updated_at,updated_at) VALUES
  ('p001','Lanzadera','juridica','ciudad',ARRAY['emprendimiento']::text[],'Aceleradora','Marina de Empresas','Centro de alto rendimiento para startups impulsado por Juan Roig. En la convocatoria de 2026 incorporó 124 startups: 40% con IA en el núcleo del producto y 88% ya facturando. Industria y salud lideran la cartera.','https://lanzadera.es/',ARRAY['aceleradora','Juan Roig','Marina de Empresas']::text[],'[{"k":"Empresas aceleradas","v":"1.700+ desde 2013"},{"k":"Hornada 2026","v":"124 startups · 40% con IA · 88% facturando"},{"k":"Ranking","v":"TOP3 de aceleradoras de España y Portugal (Financial Times, 3 años seguidos)"},{"k":"Programas","v":"A-B (aceleración) · Innovation Program · Programa 2.0"},{"k":"Dirección general","v":"Marta Nogueras · Begoña Sanchís (ayudante de dirección)"},{"k":"Directores de proyectos","v":"Miguel Milián · Salva Aliaga · Zulema García · Daniel Dancausa · Santiago Martínez · Fran Rull · Sara Leonor Medina · Roberto Chapa · Iván Sáez · Paula de Ves"},{"k":"Partners y corporate","v":"Patricia Cháfer (partners y captación) · Esteban Gallego (relaciones corporativas) · Carmen Durán · Darío Olivares · Gonzalo García"},{"k":"Contacto","v":"+34 963 568 585 · info@lanzadera.es"}]'::jsonb,'[{"k":"linkedin","u":"https://es.linkedin.com/company/lanzadera"},{"k":"x","u":"https://twitter.com/lanzaderaes"},{"k":"instagram","u":"https://www.instagram.com/lanzadera.es/"},{"k":"youtube","u":"https://www.youtube.com/user/lanzaderaTV"},{"k":"facebook","u":"https://www.facebook.com/LanzaderaEs"}]'::jsonb,ARRAY['Marina de Empresas','EDEM Escuela de Empresarios','Angels Capital','Juan Roig','Marta Nogueras','Patricia Cháfer','Esteban Gallego','Miguel Milián']::text[],'La Marina de València','sede',1,4,39.4585,-0.3285,'V',NULL,ARRAY['https://lanzadera.es/','https://lanzadera.es/equipo-lanzadera/']::text[],'contactado',NULL,1,'published','2026-09-14',now()),
  ('p002','EDEM Escuela de Empresarios','juridica','ciudad',ARRAY['emprendimiento']::text[],'Escuela de negocios','Marina de Empresas','Escuela de negocios de Marina de Empresas: grado en Empresa (ADE), másteres y programas directivos. Cantera del ecosistema emprendedor valenciano.','https://edem.eu/',ARRAY['formación','Marina de Empresas']::text[],'[{"k":"Grados","v":"ADE e Ingeniería (IGE)"},{"k":"Másteres","v":"Marketing y Venta Digital · Fintech y BI · IA, Big Data y Cloud · UX/UI · Desarrollo Web · RRHH · Logística"},{"k":"Executive","v":"EMBA · MBA Junior · programas directivos"},{"k":"Serie abierta","v":"«El arte de…» (vender, negociar, liderar, comunicar)"}]'::jsonb,'[{"k":"linkedin","u":"https://www.linkedin.com/school/edem-escuela-de-empresarios/"},{"k":"x","u":"https://twitter.com/EDEMempresarios"},{"k":"youtube","u":"https://www.youtube.com/user/EDEMEmpresariosEs"},{"k":"facebook","u":"https://www.facebook.com/EDEMescueladeempresarios"}]'::jsonb,ARRAY['Marina de Empresas','Lanzadera','Hortensia Roig']::text[],'La Marina de València','sede',1,4,39.4585,-0.3285,'V',NULL,ARRAY['https://edem.eu/']::text[],'nuevo',NULL,2,'published','2026-09-14',now()),
  ('p003','Angels Capital','juridica','ciudad',ARRAY['emprendimiento']::text[],'Sociedad de inversión','Juan Roig','Vehículo inversor de Juan Roig para startups en fase temprana. Plan de inyectar ~10 M€ en 40 compañías en dos años; ya ha recuperado los 40 M€ invertidos vía desinversiones.','https://www.angelscapital.es/',ARRAY['inversión','Juan Roig']::text[],'[{"k":"Inversión acumulada","v":"más de 40 M€"},{"k":"Participadas","v":"75 compañías"},{"k":"Cartera citada","v":"CoCircular · Citring · TRAK · IONLY · Ola Creators · Biotasmart"},{"k":"Tesis","v":"«la inversión más racional, guiada por los valores más humanos»"}]'::jsonb,'[{"k":"linkedin","u":"https://www.linkedin.com/company/angels-capital/"},{"k":"x","u":"https://twitter.com/angels_capital"}]'::jsonb,ARRAY['Juan Roig','Marina de Empresas','Lanzadera','Zubi Labs / Zubi Group']::text[],'La Marina de València','sede',1,4,39.4585,-0.3285,'V',NULL,ARRAY['https://www.angelscapital.es/']::text[],'nuevo',NULL,3,'published','2026-09-14',now()),
  ('p004','Marina de Empresas','juridica','ciudad',ARRAY['emprendimiento']::text[],'Campus emprendedor','La Marina de València','Campus que reúne EDEM, Lanzadera y Angels en la dársena del puerto. Juan Roig anunció una ampliación de 25 M€.','https://www.marinadeempresas.es/',ARRAY['campus','Juan Roig']::text[],'[{"k":"Ampliación 2026","v":"+7.600 m² hasta unos 27.000 m² · ~25 M€ en el nuevo edificio"}]'::jsonb,'[{"k":"linkedin","u":"https://www.linkedin.com/company/marinadempresas/"},{"k":"x","u":"https://twitter.com/marina_empresas"},{"k":"instagram","u":"https://www.instagram.com/marinadeempresas/"},{"k":"facebook","u":"https://www.facebook.com/marinadeempresas"}]'::jsonb,ARRAY['Lanzadera','EDEM Escuela de Empresarios','Angels Capital','Juan Roig','Ana Giménez']::text[],'La Marina de València','sede',1,4,39.4585,-0.3285,'V',NULL,ARRAY['https://www.marinadeempresas.es/']::text[],'nuevo',NULL,4,'published','2026-09-14',now()),
  ('p005','Startup Valencia','juridica','ciudad',ARRAY['emprendimiento']::text[],'Asociación del ecosistema','—','Asociación que vertebra el ecosistema startup valenciano. Creció un 36% en 2025 y su comunidad supera los 48.000 profesionales. Organiza VDS, el Observatorio y Directorio, NextTalent, Capital4Startups y el programa de ciberseguridad.','https://startupvalencia.org/',ARRAY['asociación','comunidad']::text[],'[{"k":"Sede","v":"Base 2, La Marina de València — C/ de la Travessia 15B, 46024"},{"k":"Comunidad","v":"más de 50.000 profesionales"},{"k":"Startups y scaleups","v":"más de 3.000"},{"k":"Programas","v":"VDS · Observatorio y Directorio · NextTalent · Cybersecurity Startup Program · Capital4Startups · Founders Club · Corporate Innovation Club"},{"k":"Grupos de trabajo","v":"Mobility Hub · Blockchain · DeepTech"},{"k":"Red internacional","v":"10 hubs: Ámsterdam, Copenhague, Lisboa, Medellín, Miami, Múnich, Róterdam, Tallin, La Haya"}]'::jsonb,'[{"k":"linkedin","u":"https://www.linkedin.com/company/startupvalencia/"},{"k":"x","u":"https://twitter.com/Startup_VLC"},{"k":"instagram","u":"https://www.instagram.com/startupvalencia/"},{"k":"youtube","u":"https://www.youtube.com/channel/UCX5EeENSUoxoxHLxPxarM2A"},{"k":"tiktok","u":"https://www.tiktok.com/@startupvalencia"},{"k":"facebook","u":"https://www.facebook.com/StartupValencia/"}]'::jsonb,ARRAY['VDS — Valencia Digital Summit','Base 2','Juan Luis Hortelano','Nacho Mas','The Terminal Hub']::text[],'C. de la Travessia, Poblats Marítims, 46024 València','sede',1,4,39.4592,-0.327,'V',NULL,ARRAY['https://startupvalencia.org/']::text[],'nuevo',NULL,5,'published','2026-09-14',now()),
  ('p006','VDS — Valencia Digital Summit','juridica','ciudad',ARRAY['emprendimiento']::text[],'Evento y organización','Startup Valencia','Gran encuentro global de startups, corporaciones e inversores. Su edición de 2026 generó un impacto económico estimado en 26 M€ para la ciudad.','https://vds.tech/',ARRAY['evento','internacional']::text[],'[{"k":"Edición 2026","v":"21 y 22 de octubre · Ciutat de les Arts i les Ciències"},{"k":"Asistentes","v":"12.000+ de más de 120 países"},{"k":"Startups y scaleups","v":"3.000+"},{"k":"Corporaciones","v":"1.500+"},{"k":"Inversores","v":"800+, con más de 300.000 M€ bajo gestión"},{"k":"Ponentes","v":"600+"},{"k":"Tracks","v":"AI & Deep Tech · Climate & Energy · Defense & Aerospace · Talent & Future of Work · Health · Mobility & Logistics · Digital Wealth · Policy"},{"k":"Pases","v":"Attendee · Business · Investor"}]'::jsonb,'[{"k":"linkedin","u":"https://www.linkedin.com/company/vds-event/"},{"k":"x","u":"https://x.com/VDS_event"},{"k":"instagram","u":"https://www.instagram.com/vds.tech"},{"k":"youtube","u":"http://www.youtube.com/@VDS_event"},{"k":"tiktok","u":"https://www.tiktok.com/@vds_tech"},{"k":"facebook","u":"https://www.facebook.com/valenciadigitalsummit/"}]'::jsonb,ARRAY['Startup Valencia','Nacho Mas']::text[],'C. de la Travessia, Poblats Marítims, 46024 València','sede',1,4,39.4592,-0.327,'V',NULL,ARRAY['https://vds.tech/']::text[],'nuevo',NULL,6,'published','2026-09-14',now()),
  ('p007','BIGBAN Inversores Privados','juridica','ciudad',ARRAY['emprendimiento']::text[],'Red de business angels','—','Asociación española de business angels con sede en La Marina de València. Organiza el BIGBAN Investors Congress y la Escuela de Business Angels.','https://bigban.org/',ARRAY['inversión','business angels']::text[],'[{"k":"Presidente","v":"Pedro de Álava (Clave Capital)"},{"k":"Dirección ejecutiva","v":"Alberto Andújar"},{"k":"Vicepresidencias","v":"Tom Horsey (inversión) · Luz Adell (dealflow) · Nacho Alonso (coinversión) · Carlos Caballero (transferencia) · Jesús Ávila (innovación abierta)"},{"k":"Tesorería y secretaría","v":"David Mor (Borealis) · Cristian Cañadas (Aktion Legal)"},{"k":"Vocales","v":"Patricia Fraile · Jordi Rivera · Juanjo Mostazo · Manuel Juliá · Helena Torras"},{"k":"Teléfono","v":"+34 623 001 126"}]'::jsonb,'[]'::jsonb,ARRAY['Pedro de Álava','Alberto Andújar','Cristian Cañadas','Clave Capital','Aktion Legal']::text[],'C/ de la Travessia 15E, Base 5, 46024 València','sede',1,4,39.4592,-0.327,'V',NULL,ARRAY['https://bigban.org/equipo-junta/','https://bigban.org/conoce-bigban/']::text[],'nuevo',NULL,7,'published','2026-09-14',now()),
  ('p008','Innsomnia','juridica','ciudad',ARRAY['emprendimiento']::text[],'Aceleradora corporativa','La Marina de València','Hub de innovación abierta y aceleradora corporativa, pionera en fintech e insurtech en España. Sede en Travessía 15B (Base 2), La Marina. Digital Innovation Hub europeo.','https://innsomniagroup.com/',ARRAY['innovación abierta','fintech','insurtech']::text[],'[{"k":"Sedes","v":"València (Travessia 15B, Base 2) · Madrid (Pl. de la Castellana 89) · Miami"},{"k":"Teléfono","v":"+34 960 420 421"},{"k":"Alcance","v":"más de 40 corporaciones"}]'::jsonb,'[{"k":"linkedin","u":"https://www.linkedin.com/company/10805922/"},{"k":"x","u":"https://x.com/Inn_Somnia"},{"k":"instagram","u":"https://www.instagram.com/innsomnia_group/"}]'::jsonb,ARRAY['Base 2','Startup Valencia','Francisco (Fran) Estevan']::text[],'C/ de la Travessia 15B, Base 2, 46024 València','sede',1,4,39.4592,-0.327,'V',NULL,ARRAY['https://innsomniagroup.com/']::text[],'nuevo',NULL,8,'published','2026-09-14',now()),
  ('p009','Draper B1','juridica','ciudad',ARRAY['emprendimiento']::text[],'Venture capital','—','Fondo de capital riesgo con sede en Valencia, parte de la red Draper Venture Network. Invierte en fases semilla y serie A.','https://draperb1.vc/',ARRAY['VC','inversión']::text[],'[{"k":"Fase","v":"semilla y early stage"},{"k":"Red","v":"Draper Venture Network"},{"k":"Cartera citada","v":"Erudit · FourVenues · APlanet · Traventia (exit) · Signaturit (exit) · Skitude (exit)"}]'::jsonb,'[{"k":"linkedin","u":"https://www.linkedin.com/company/draperb1/"},{"k":"x","u":"https://twitter.com/draperb1_vc"},{"k":"medium","u":"https://medium.com/draperb1"}]'::jsonb,ARRAY['Fourvenues']::text[],NULL,NULL,NULL,NULL,NULL,NULL,'V',NULL,ARRAY['https://draperb1.vc/']::text[],'nuevo',NULL,9,'published','2026-09-14',now()),
  ('p010','Zubi Labs / Zubi Group','juridica','ciudad',ARRAY['emprendimiento']::text[],'Venture builder de impacto','Iker Marcaide','Venture builder que construye empresas de impacto desde Valencia (Matteco, Imagine Montessori, Zubi Cities…).','https://zubilabs.com/',ARRAY['impacto','venture builder']::text[],'[{"k":"Sedes","v":"València (C. de la Travessia) · Madrid (Velázquez 80) · Barcelona"},{"k":"Cartera","v":"Matteco · CoCircular · Kampe · Nido · TeraDx · Devera · Skills4Impact · ZeroNet · Greenest · Woodea"},{"k":"Equipo citado","v":"Pablo Lara, managing partner"}]'::jsonb,'[{"k":"linkedin","u":"https://www.linkedin.com/company/zubi-labs/"}]'::jsonb,ARRAY['Iker Marcaide','Matteco','Fernando Marzal','Angels Capital']::text[],'C. de la Travessia, Poblats Marítims, 46024 València','sede',1,4,39.4592,-0.327,'V',NULL,ARRAY['https://zubilabs.com/']::text[],'nuevo',NULL,10,'published','2026-09-14',now()),
  ('p011','CEEI València','juridica','ciudad',ARRAY['emprendimiento']::text[],'Centro de empresas innovadoras','Generalitat / IVACE','Centro Europeo de Empresas Innovadoras: incubación, asesoramiento y la plataforma EmprenemJunts, que agrega convocatorias y eventos de toda la Comunitat.','https://ceeivalencia.emprenemjunts.es/',ARRAY['incubadora','convocatorias']::text[],'[]'::jsonb,'[]'::jsonb,ARRAY[]::text[],'Plaça de Manises 1 (Palau de la Generalitat)','sede',1,1,39.476,-0.378,'V',NULL,ARRAY[]::text[],'nuevo',NULL,11,'published','2026-09-14',now()),
  ('p012','Las Naves','juridica','ciudad',ARRAY['emprendimiento']::text[],'Centro de innovación social y urbana','Ajuntament de València','Edificio municipal de innovación en Camins al Grau (C/ Joan Verdeguer 16). Desde 2026 lasnaves.com redirige a València Innovation Capital: el edificio sigue siendo la sede, pero la marca operativa es VIC.','https://www.lasnaves.com/',ARRAY['innovación social','municipal']::text[],'[{"k":"Dirección","v":"C/ Joan Verdeguer 16, 46024 València"},{"k":"Edificio hermano","v":"La Harinera, C/ Joan Verdeguer 32"},{"k":"Nota","v":"lasnaves.com redirige hoy a valenciainnovationcapital.com"}]'::jsonb,'[]'::jsonb,ARRAY['València Innovation Capital']::text[],'C/ Joan Verdeguer 16, 46024 València','sede',1,4,39.464,-0.349,'V',NULL,ARRAY['https://valenciainnovationcapital.com/']::text[],'nuevo',NULL,12,'published','2026-09-14',now()),
  ('p013','València Innovation Capital','juridica','ciudad',ARRAY['emprendimiento']::text[],'Programa municipal de innovación','Ajuntament de València','Marca y paraguas de las políticas de innovación del Ayuntamiento: subvenciones early stage y seed, Premios a la Innovación y apoyo a la participación en VDS.','https://valenciainnovationcapital.com/',ARRAY['ayudas','municipal']::text[],'[{"k":"Sedes","v":"Las Naves (C/ Joan Verdeguer 16) y La Harinera (C/ Joan Verdeguer 32)"},{"k":"Teléfono","v":"963 910 477"},{"k":"Programas","v":"Sandbox Urbano · City Challenges · programas de aceleración · Innovation Labs · proyectos europeos · i-team València · 46 Valencia Tech Hub · Valencia Innovation Alliance"},{"k":"Convocatorias","v":"VLC Startup Awards · subvenciones early stage y seed · Premios a la Innovación"}]'::jsonb,'[{"k":"linkedin","u":"https://www.linkedin.com/company/vlc-innovation/"},{"k":"x","u":"https://x.com/VLCInnovation"},{"k":"instagram","u":"https://www.instagram.com/VLCInnovation/"},{"k":"youtube","u":"https://www.youtube.com/@VLCInnovation"},{"k":"facebook","u":"https://www.facebook.com/VLCInnovation"}]'::jsonb,ARRAY['Las Naves','Ajuntament de València — Participación Ciudadana','María José Catalá']::text[],'C/ Joan Verdeguer 16, 46024 València','sede',1,4,39.464,-0.349,'V',NULL,ARRAY['https://valenciainnovationcapital.com/']::text[],'nuevo',NULL,13,'published','2026-09-14',now()),
  ('p014','Parc Científic de la Universitat de València','juridica','ciudad',ARRAY['emprendimiento']::text[],'Parque científico','Universitat de València','Parque científico en Paterna con concentración de biotecnológicas y spin-offs. Impulsa con la FPCUV la incubadora de inteligencia artificial IATecUV.','https://www.pcuv.es/',ARRAY['deep tech','spin-off','biotech']::text[],'[]'::jsonb,'[{"k":"linkedin","u":"https://es.linkedin.com/company/parccientificuv"}]'::jsonb,ARRAY[]::text[],'Av. de Blasco Ibáñez 13','sede',1,4,39.479,-0.348,'V',NULL,ARRAY['https://www.pcuv.es/']::text[],'nuevo',NULL,14,'published','2026-09-14',now()),
  ('p015','Instituto IDEAS UPV','juridica','ciudad',ARRAY['emprendimiento']::text[],'Creación de empresas','Universitat Politècnica de València','Estructura de la UPV para la creación de empresas de base tecnológica a partir de investigación universitaria.','https://innovacion.upv.es/',ARRAY['universidad','spin-off']::text[],'[]'::jsonb,'[]'::jsonb,ARRAY[]::text[],'Camí de Vera s/n, 46022 València','sede',1,4,39.4812,-0.3408,'V',NULL,ARRAY[]::text[],'nuevo',NULL,15,'published','2026-09-14',now()),
  ('p016','Comité Tech Transfer','juridica','ciudad',ARRAY['emprendimiento']::text[],'Transferencia de tecnología','Startup Valencia + UPV','Comité que impulsa startups valencianas nacidas de transferir tecnología de la investigación al mercado.','https://innovacion.upv.es/en/el-comite-tech-transfer-impulsara-startups-valencianas-que-transfieran-tecnologia-de-la-investigacion-upv-al-mercado/',ARRAY['transferencia','deep tech']::text[],'[]'::jsonb,'[]'::jsonb,ARRAY[]::text[],'C. de la Travessia, Poblats Marítims, 46024 València','sede',1,4,39.4592,-0.327,'V',NULL,ARRAY[]::text[],'nuevo',NULL,16,'published','2026-09-14',now()),
  ('p017','ITI — Instituto Tecnológico de Informática','juridica','ciudad',ARRAY['tecnologia']::text[],'Centro tecnológico','UPV','Centro tecnológico especializado en IA, datos e informática avanzada aplicada a la industria.',NULL,ARRAY['IA','centro tecnológico']::text[],'[]'::jsonb,'[]'::jsonb,ARRAY[]::text[],'Camí de Vera s/n, 46022 València','sede',1,4,39.4812,-0.3408,'E',NULL,ARRAY[]::text[],'nuevo',NULL,17,'published','2026-09-14',now()),
  ('p018','REDIT','juridica','ciudad',ARRAY['tecnologia']::text[],'Red de institutos tecnológicos','Comunitat Valenciana','Red que agrupa los institutos tecnológicos valencianos (AIMPLAS, AINIA, ITE, IBV, AIDIMME, ITENE, AITEX…).',NULL,ARRAY['I+D','industria']::text[],'[]'::jsonb,'[]'::jsonb,ARRAY[]::text[],'Av. Benjamín Franklin 5-11, Parc Tecnològic, Paterna','sede',2,2,39.5104,-0.4218,'E',NULL,ARRAY[]::text[],'nuevo',NULL,18,'published','2026-09-14',now()),
