  ('p179','Terreta Hub','juridica','producto',ARRAY['emprendimiento']::text[],'Producto · red social de València','Versa','Red social de València: perfil, gente y lo que pasa en la ciudad. React 19 + Vite + TS + Supabase + Leaflet (repo Portuno/terretahub). Moneda blanda: Terris. Módulos: Ágora, Mapa, Miembros, Proyectos, Eventos, Propiedades, Biblioteca, L''Almoina, QR.','https://www.terretahub.com',ARRAY['producto','comunidad','Versa']::text[],'[{"k":"Qué es","v":"«La red social de Valencia: perfil, gente y lo que pasa en la ciudad». La propia web aclara que no es un directorio de startups ni una red corporativa."},{"k":"Módulos","v":"Perfil · Ágora · Proyectos · Quedadas"},{"k":"Desambiguación","v":"La web ya declara en público que Terreta Hub no está afiliada ni es la misma entidad que Terreta Business Hub S.L."}]'::jsonb,'[{"k":"x","u":"https://twitter.com/terretahub"}]'::jsonb,ARRAY['Versa Producciones','Lautaro Joaquín Sarni','Camila Verdún Lomba','El Fotográpher','Verlo Por Vos','Base44']::text[],NULL,NULL,NULL,NULL,NULL,NULL,'V',NULL,ARRAY['https://www.terretahub.com/']::text[],'nuevo',NULL,179,'published','2026-09-14',now()),
