  ('p239','BioHub VLC','juridica','ciudad',ARRAY['salud']::text[],'Hub de life sciences','La Marina de València','Se presenta como el primer centro empresarial español de gestión privada dedicado a compañías de life sciences: aloja biotecnológicas, farma y tecnología sanitaria en fase de crecimiento y les conecta con inversión.','https://biohubvlc.es/',ARRAY['biotech','hub','La Marina','life sciences']::text[],'[{"k":"CEO","v":"Ángela Pérez"},{"k":"Equipo","v":"Fernando Ibáñez (corporate) · Virginia Beltrán (coordinación) · David Gómez (comunicación) · Ramón Guanter (redes) · Reme Hidalgo (eventos)"},{"k":"Socios","v":"Bioval · BioZell Ventures · Club Bio · La Marina de València"}]'::jsonb,'[{"k":"linkedin","u":"https://es.linkedin.com/company/biohub-vlc"},{"k":"instagram","u":"https://www.instagram.com/biohubvlc"}]'::jsonb,ARRAY['Ángela Pérez','Bioval','BioZell Ventures','Club Bio','Fernando Ibáñez','Virginia Beltrán']::text[],'C/ de la Travessia 15E, La Marina, 46024 València','sede',1,4,39.4592,-0.327,'V',NULL,ARRAY['https://biohubvlc.es/']::text[],'nuevo',NULL,239,'published','2026-09-14',now()),
  ('p240','BioZell Ventures','juridica','ciudad',ARRAY['salud']::text[],'Inversión en salud','València','Vehículo de inversión privada en salud del entorno de BioHub VLC y Bioval; ya ha cerrado su primera inversión.','https://biohubvlc.es/biozell-realiza-su-primera-inversion-en-salud/',ARRAY['inversión','biotech']::text[],'[]'::jsonb,'[]'::jsonb,ARRAY['BioHub VLC','Bioval']::text[],NULL,'sede',1,4,39.4592,-0.327,'V',NULL,ARRAY['https://biohubvlc.es/biozell-realiza-su-primera-inversion-en-salud/']::text[],'nuevo',NULL,240,'published','2026-09-14',now()),
  ('p241','Club Bio','juridica','ciudad',ARRAY['salud']::text[],'Círculo empresarial','Bioval + BioHub VLC','Primer círculo empresarial valenciano que pone la ciencia en el centro de los negocios, creado conjuntamente por Bioval y BioHub VLC.','https://www.bioval.org/noticias/bioval-y-biohub-crean-club-bio-el-primer-circulo-empresarial-que-pone-a-la-ciencia-en-el-centro-de-los-negocios-en-valencia/',ARRAY['networking','biotech']::text[],'[]'::jsonb,'[]'::jsonb,ARRAY['Bioval','BioHub VLC']::text[],NULL,'sede',1,4,39.4592,-0.327,'V',NULL,ARRAY['https://www.bioval.org/noticias/bioval-y-biohub-crean-club-bio-el-primer-circulo-empresarial-que-pone-a-la-ciencia-en-el-centro-de-los-negocios-en-valencia/']::text[],'nuevo',NULL,241,'published','2026-09-14',now())
