  ('p276','Teatro Olympia','juridica','ciudad',ARRAY['entretenimiento']::text[],'Teatro','Ciutat Vella','Teatro privado histórico de València, en pleno centro, con cartelera de comedia, musicales y grandes producciones.','https://www.teatro-olympia.com/',ARRAY['teatro','musicales']::text[],'[]'::jsonb,'[]'::jsonb,ARRAY[]::text[],'C/ de Sant Vicent Màrtir 44, 46002 València','calle',1,1,39.469,-0.3765,'V',NULL,ARRAY['https://www.teatro-olympia.com/']::text[],'nuevo',NULL,276,'published','2026-09-14',now()),
  ('p277','Teatre Rialto','juridica','ciudad',ARRAY['arte']::text[],'Teatro público','Institut Valencià de Cultura','Teatro del IVC en la plaza del Ayuntamiento, sede habitual de la producción escénica valenciana contemporánea.','https://ivc.gva.es/es/ivc/programacion-ivc/teatro-rialto-de-valencia',ARRAY['teatro','IVC','artes escénicas']::text[],'[]'::jsonb,'[]'::jsonb,ARRAY['Institut Valencià de Cultura (IVC)']::text[],'Plaça de l''Ajuntament 17, 46002 València','calle',1,1,39.4697,-0.3772,'V',NULL,ARRAY['https://ivc.gva.es/es/ivc/programacion-ivc/teatro-rialto-de-valencia']::text[],'nuevo',NULL,277,'published','2026-09-14',now()),
  ('p278','Teatre Talia','juridica','ciudad',ARRAY['entretenimiento']::text[],'Teatro','Ciutat Vella','Teatro municipal en Ciutat Vella con programación escénica estable.','https://www.valencia.es/cas/agenda-de-la-ciudad/-/content/teatre-talia-programacio',ARRAY['teatro','municipal']::text[],'[]'::jsonb,'[]'::jsonb,ARRAY[]::text[],'C/ dels Cavallers 31, 46001 València','calle',1,1,39.473,-0.376,'E',NULL,ARRAY['https://www.valencia.es/cas/agenda-de-la-ciudad/-/content/teatre-talia-programacio']::text[],'nuevo',NULL,278,'published','2026-09-14',now()),
  ('p279','AVIV — Asociación Valenciana de la Industria del Videojuego','juridica','ciudad',ARRAY['tecnologia']::text[],'Asociación sectorial','Comunitat Valenciana','Primera asociación de la industria valenciana del videojuego, presentada en OWN 2026. Representa los intereses del sector y le da voz ante las instituciones. Impulsada desde la delegación de Innovación del Ayuntamiento.','https://www.valencia.es/cas/actualidad/-/content/impulso-industria-videojuego',ARRAY['videojuegos','asociación','sector']::text[],'[{"k":"Impulsores citados","v":"Carles Pons (No Soon Tech Lab) · Javier Giménez (Digital Sun) · Jaime Torres (ESAT) · Javier Carrión (ENCOM) · Axel García (Brave Zebra) · Ramón Nafria"}]'::jsonb,'[]'::jsonb,ARRAY['Digital Sun Games','Encom Games','Brave Zebra','No Soon Tech Lab','ESAT','Paula Llobet']::text[],NULL,NULL,NULL,NULL,NULL,NULL,'V',NULL,ARRAY['https://www.valencia.es/cas/actualidad/-/content/impulso-industria-videojuego']::text[],'nuevo',NULL,279,'published','2026-09-14',now()),
  ('p280','Digital Sun Games','juridica','ciudad',ARRAY['entretenimiento']::text[],'Estudio de videojuegos','València','Estudio independiente con más de 50 personas. Autor de Moonlighter (más de 2,5 millones de copias), The Mageseeker: A League of Legends Story y Cataclismo, su juego mejor valorado.','https://digitalsungames.com/',ARRAY['videojuegos','estudio','indie']::text[],'[{"k":"Equipo","v":"más de 50 personas"},{"k":"Juegos","v":"Moonlighter · The Mageseeker · Cataclismo · Moonlighter 2: The Endless Vault"},{"k":"Fundadores","v":"Javi Giménez (CEO) y Rubén Picó (COO)"}]'::jsonb,'[{"k":"x","u":"https://twitter.com/digitalsungames"},{"k":"instagram","u":"https://www.instagram.com/digitalsungames/"},{"k":"tiktok","u":"https://www.tiktok.com/@digitalsungames"},{"k":"linkedin","u":"https://es.linkedin.com/company/wildframemedia"},{"k":"facebook","u":"https://www.facebook.com/digitalsungames"},{"k":"steam","u":"https://store.steampowered.com/publisher/digitalsun"}]'::jsonb,ARRAY['Javi Giménez','Rubén Picó','AVIV — Asociación Valenciana de la Industria del Videojuego']::text[],NULL,NULL,NULL,NULL,NULL,NULL,'V',NULL,ARRAY['https://digitalsungames.com/about-us/']::text[],'nuevo',NULL,280,'published','2026-09-14',now()),
  ('p281','Encom Games','juridica','ciudad',ARRAY['entretenimiento']::text[],'Estudio y organizador de eventos','València','Compañía valenciana de videojuegos que ejecuta los programas municipales València Game City y el festival OWN mediante convenio con el Ayuntamiento.','https://www.valenciaextra.com/es/valencia/valencia-impulsa-el-ecosistema-del-videojuego-con-300-000-euros-para-valencia-game-city-y-own-2026_585545_102.html',ARRAY['videojuegos','eventos','esports']::text[],'[]'::jsonb,'[]'::jsonb,ARRAY['OWN — Open World Now','València Game City','Javier Carrión','AVIV — Asociación Valenciana de la Industria del Videojuego']::text[],NULL,NULL,NULL,NULL,NULL,NULL,'V',NULL,ARRAY['https://www.valenciaextra.com/es/valencia/valencia-impulsa-el-ecosistema-del-videojuego-con-300-000-euros-para-valencia-game-city-y-own-2026_585545_102.html']::text[],'nuevo',NULL,281,'published','2026-09-14',now()),
  ('p282','Brave Zebra','juridica','ciudad',ARRAY['entretenimiento']::text[],'Estudio de videojuegos','València','Estudio valenciano de videojuegos, entre los impulsores de AVIV.',NULL,ARRAY['videojuegos','estudio']::text[],'[]'::jsonb,'[]'::jsonb,ARRAY['AVIV — Asociación Valenciana de la Industria del Videojuego','Axel García']::text[],NULL,NULL,NULL,NULL,NULL,NULL,'E',NULL,ARRAY['https://www.valencia.es/cas/actualidad/-/content/impulso-industria-videojuego']::text[],'nuevo',NULL,282,'published','2026-09-14',now()),
  ('p283','No Soon Tech Lab','juridica','ciudad',ARRAY['tecnologia']::text[],'Estudio y laboratorio tecnológico','València','Laboratorio tecnológico valenciano del entorno del videojuego y la tecnología inmersiva; entre los impulsores de AVIV.',NULL,ARRAY['videojuegos','XR','tecnología']::text[],'[]'::jsonb,'[]'::jsonb,ARRAY['AVIV — Asociación Valenciana de la Industria del Videojuego','Carles Pons']::text[],NULL,NULL,NULL,NULL,NULL,NULL,'E',NULL,ARRAY['https://www.valencia.es/cas/actualidad/-/content/impulso-industria-videojuego']::text[],'nuevo',NULL,283,'published','2026-09-14',now()),
  ('p284','ESAT','juridica','ciudad',ARRAY['tecnologia']::text[],'Escuela de videojuegos y tecnología','València','Escuela superior de arte y tecnología: forma a buena parte de los desarrolladores de videojuegos y artistas digitales valencianos.',NULL,ARRAY['formación','videojuegos','arte digital']::text[],'[]'::jsonb,'[]'::jsonb,ARRAY['AVIV — Asociación Valenciana de la Industria del Videojuego','Jaime Torres']::text[],NULL,NULL,NULL,NULL,NULL,NULL,'E',NULL,ARRAY['https://www.valencia.es/cas/actualidad/-/content/impulso-industria-videojuego']::text[],'nuevo',NULL,284,'published','2026-09-14',now()),
  ('p285','València Game City','juridica','ciudad',ARRAY['entretenimiento']::text[],'Programa municipal del videojuego','Ajuntament de València','Programa municipal que da visibilidad al ecosistema valenciano del videojuego: ayudas a estudios locales, formación en XR, encuentros de comunidad y presencia en ferias. Dotado con 150.000 € en 2026.',NULL,ARRAY['videojuegos','municipal','XR']::text[],'[{"k":"Dotación 2026","v":"150.000 € · otros 150.000 € para OWN"},{"k":"Ejecuta","v":"Encom Games"},{"k":"En OWN 2026","v":"pabellón con más de 20 proyectos valencianos"}]'::jsonb,'[]'::jsonb,ARRAY['Encom Games','OWN — Open World Now','Paula Llobet','València Innovation Capital']::text[],NULL,NULL,NULL,NULL,NULL,NULL,'V',NULL,ARRAY['https://www.valenciaextra.com/es/valencia/valencia-impulsa-el-ecosistema-del-videojuego-con-300-000-euros-para-valencia-game-city-y-own-2026_585545_102.html']::text[],'nuevo',NULL,285,'published','2026-09-14',now()),
  ('p293','Valencia Film Office','juridica','ciudad',ARRAY['arte']::text[],'Oficina de rodajes','Fundació Visit València','Servicio municipal de apoyo a la producción audiovisual: permisos, localizaciones, contacto con profesionales y orientación sobre incentivos fiscales de hasta el 30%. València acogió 135 rodajes en 2025.','https://www.valenciafilmoffice.org/',ARRAY['cine','audiovisual','rodajes','municipal']::text[],'[{"k":"Rodajes en 2025","v":"135 producciones"},{"k":"Incentivo fiscal","v":"hasta el 30%"},{"k":"Depende de","v":"Fundació Visit València"}]'::jsonb,'[]'::jsonb,ARRAY['Valencia Convention Bureau','Mostra de València — Cinema del Mediterrani']::text[],NULL,NULL,NULL,NULL,NULL,NULL,'V',NULL,ARRAY['https://www.valenciafilmoffice.org/','https://valenciaplaza.com/cine-audiovisual-valencia-comunitat-valenciana/valencia-ha-acogido-135-rodajes-de-producciones-durante-2025']::text[],'nuevo',NULL,293,'published','2026-09-14',now()),
  ('p294','Mostra de València — Cinema del Mediterrani','juridica','ciudad',ARRAY['arte']::text[],'Festival de cine','Ajuntament de València','Festival de cine mediterráneo de la ciudad, recuperado tras seis años de paréntesis. Incluye València Film Afers, su mercado y foro profesional.','https://lamostradevalencia.com/',ARRAY['cine','festival','mediterráneo']::text[],'[{"k":"Sección profesional","v":"València Film Afers"}]'::jsonb,'[]'::jsonb,ARRAY['Valencia Film Office','Institut Valencià de Cultura (IVC)']::text[],NULL,NULL,NULL,NULL,NULL,NULL,'V',NULL,ARRAY['https://lamostradevalencia.com/','https://www.valencia.es/-/vuelve-la-mostra-de-valencia-cinema-del-mediterrani-tras-un-parentesis-de-seis-anos-']::text[],'nuevo',NULL,294,'published','2026-09-14',now())
